#!/usr/bin/env bash
# step40 — Checkout rebuilt into the site shell (dark theme, header/footer),
#          aligned payment methods + real SVG logos, Transaction ID field removed,
#          payment proof REQUIRED, "You might also like" similar products.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step40-$TS
JS_MD5="41270c56438a2ec331db707a1508264f"
EJS_MD5="dbce8f7ac81749428f4e01532ae03ea7"

echo "==> backup -> $BAK"
mkdir -p "$BAK/routes" "$BAK/views"
cp "$APP/routes/checkout.js" "$BAK/routes/checkout.js"
cp "$APP/views/checkout.ejs" "$BAK/views/checkout.ejs"

restore(){ echo "!! rolling back checkout files"; cp "$BAK/routes/checkout.js" "$APP/routes/checkout.js"; cp "$BAK/views/checkout.ejs" "$APP/views/checkout.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR

echo "==> writing routes/checkout.js"
cat > /tmp/gsz-co-js.b64 <<'B64A'

B64A
base64 -d /tmp/gsz-co-js.b64 > "$APP/routes/checkout.js"; rm -f /tmp/gsz-co-js.b64

echo "==> writing views/checkout.ejs"
cat > /tmp/gsz-co-ejs.b64 <<'B64B'

B64B
base64 -d /tmp/gsz-co-ejs.b64 > "$APP/views/checkout.ejs"; rm -f /tmp/gsz-co-ejs.b64

G1=$(md5sum "$APP/routes/checkout.js" | awk '{print $1}')
G2=$(md5sum "$APP/views/checkout.ejs" | awk '{print $1}')
echo "   js  $G1 (expect $JS_MD5)"
echo "   ejs $G2 (expect $EJS_MD5)"
[ "$G1" = "$JS_MD5" ] || { echo "!! checkout.js md5 mismatch"; false; }
[ "$G2" = "$EJS_MD5" ] || { echo "!! checkout.ejs md5 mismatch"; false; }

echo "==> node --check checkout.js"
node --check "$APP/routes/checkout.js"

echo "==> ejs compile check checkout.ejs"
node -e '
const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");
ejs.compile(fs.readFileSync("/opt/gsz/views/checkout.ejs","utf8"),{filename:"/opt/gsz/views/checkout.ejs"});
console.log("   compile OK");
'

echo "==> pm2 restart gsz"
pm2 restart gsz --update-env >/dev/null
sleep 2

echo "==> find a live product slug"
HOME_HTML=$(curl -s -m 15 http://127.0.0.1:3900/)
SLUG=$(printf '%s' "$HOME_HTML" | grep -oE '/product/[a-z0-9-]+' | head -1 | sed 's#/product/##')
[ -n "$SLUG" ] || { echo "!! could not find a product slug on home page"; false; }
echo "   using slug: $SLUG"

echo "==> fetch checkout page"
CO=$(curl -s -m 15 "http://127.0.0.1:3900/checkout?p=$SLUG&plan=0&region=PK")
printf '%s' "$CO" | grep -q '</html>' || { echo "!! checkout did not render"; false; }
printf '%s' "$CO" | grep -qi 'Checkout error:' && { echo "!! checkout route threw"; false; } || true
printf '%s' "$CO" | grep -qi 'Internal Server Error' && { echo "!! internal server error"; false; } || true
printf '%s' "$CO" | grep -q 'class="hd"' || { echo "!! site header not included (shell missing)"; false; }
printf '%s' "$CO" | grep -q 'pm-logo' || { echo "!! payment logos missing"; false; }
printf '%s' "$CO" | grep -q 'You might also like' || { echo "!! similar products missing"; false; }
printf '%s' "$CO" | grep -qE 'name="proof"[^>]*required' || { echo "!! proof not required"; false; }
printf '%s' "$CO" | grep -qi 'Transaction ID' && { echo "!! Transaction ID field still present"; false; } || true

echo "==> home still renders"
printf '%s' "$HOME_HTML" | grep -q '</html>' || { echo "!! home broken"; false; }

trap - ERR
echo "==> step40 OK — checkout rebuilt. Backup: $BAK"
